</head>
<body>

  <h1>Maze Bot Exploration</h1>

  <div class="dashboard">
    <div class="stat-item">
      <span class="stat-label">Timer (Ticks)</span>
      <span class="stat-value" id="timer">0</span>
    </div>

    <div class="stat-item">
      <span class="stat-label">Completed</span>
      <span class="stat-value" id="completed">0 / 24</span>
    </div>

    <div class="controls">
      <button id="reset">Reset</button>
      <button id="playBtn">Pause</button>
      <button id="stepBtn">Step</button>
      <input type="number" id="seedInput" class="seed-input" placeholder="Seed" />
    </div>
  </div>

  <div id="maze">
    <canvas id="mazeCanvas" width="500" height="500"></canvas>
  </div>

  <script>
    (function() {
      // Mulberry32 Seeded PRNG
      function createPRNG(seed) {
        let s = Number(seed) >>> 0;
        return function() {
          s = (s + 0x6D2B79F5) | 0;
          let t = Math.imul(s ^ (s >>> 15), 1 | s);
          t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
          return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
      }

      // Generate all 24 permutations of direction priorities
      function getPermutations(arr) {
        if (arr.length === 0) return [[]];
        let res = [];
        for (let i = 0; i < arr.length; i++) {
          let rest = arr.slice(0, i).concat(arr.slice(i + 1));
          let inner = getPermutations(rest);
          for (let p of inner) {
            res.push([arr[i], ...p]);
          }
        }
        return res;
      }

      const ROWS = 20;
      const COLS = 20;
      const NUM_BOTS = 24;

      let grid = [];
      let currentSeed = 12345;
      let prng = createPRNG(currentSeed);
      let isPlaying = true;
      let lastFrameTime = performance.now();
      let animProgress = 1.0;
      const TICK_INTERVAL = 80; // ms per tick in visual playback

      // 24 vibrant distinct colors for bots
      const BOT_COLORS = Array.from({ length: NUM_BOTS }, (_, i) => {
        const hue = (i * 360 / NUM_BOTS) % 360;
        return `hsl(${hue}, 85%, 60%)`;
      });

      // Perfect Maze Generator (Recursive Backtracking using PRNG)
      function generateMaze(rows, cols, rng) {
        const g = Array.from({ length: rows }, () =>
          Array.from({ length: cols }, () => ({
            n: true, e: true, s: true, w: true, visited: false
          }))
        );

        const stack = [{ r: 0, c: 0 }];
        g[0][0].visited = true;

        while (stack.length > 0) {
          const current = stack[stack.length - 1];
          const unvisited = [];

          if (current.r > 0 && !g[current.r - 1][current.c].visited) {
            unvisited.push({ dir: 'N', r: current.r - 1, c: current.c });
          }
          if (current.c < cols - 1 && !g[current.r][current.c + 1].visited) {
            unvisited.push({ dir: 'E', r: current.r, c: current.c + 1 });
          }
          if (current.r < rows - 1 && !g[current.r + 1][current.c].visited) {
            unvisited.push({ dir: 'S', r: current.r + 1, c: current.c });
          }
          if (current.c > 0 && !g[current.r][current.c - 1].visited) {
            unvisited.push({ dir: 'W', r: current.r, c: current.c - 1 });
          }

          if (unvisited.length > 0) {
            const idx = Math.floor(rng() * unvisited.length);
            const chosen = unvisited[idx];

            if (chosen.dir === 'N') {
              g[current.r][current.c].n = false;
              g[chosen.r][chosen.c].s = false;
            } else if (chosen.dir === 'E') {
              g[current.r][current.c].e = false;
              g[chosen.r][chosen.c].w = false;
            } else if (chosen.dir === 'S') {
              g[current.r][current.c].s = false;
              g[chosen.r][chosen.c].n = false;
            } else if (chosen.dir === 'W') {
              g[current.r][current.c].w = false;
              g[chosen.r][chosen.c].e = false;
            }

            g[chosen.r][chosen.c].visited = true;
            stack.push({ r: chosen.r, c: chosen.c });
          } else {
            stack.pop();
          }
        }

        return g;
      }

      // Step individual bot using DFS/Tremaux local exploration
      function stepBot(bot, currentTick) {
        if (bot.finishTick !== null) return;

        const cur = bot.stack[bot.stack.length - 1];

        if (cur.r === game.exit.r && cur.c === game.exit.c) {
          bot.finishTick = currentTick;
          return;
        }

        const cellWalls = game.walls(cur.r, cur.c);
        let foundNext = null;

        for (const d of bot.dirOrder) {
          let wall = false;
          let nr = cur.r, nc = cur.c;

          if (d === 'N') { wall = cellWalls.n; nr--; }
          else if (d === 'E') { wall = cellWalls.e; nc++; }
          else if (d === 'S') { wall = cellWalls.s; nr++; }
          else if (d === 'W') { wall = cellWalls.w; nc--; }

          if (!wall) {
            const key = `${nr},${nc}`;
            if (!bot.visitedSet.has(key) && !bot.deadSet.has(key)) {
              foundNext = { r: nr, c: nc, key };
              break;
            }
          }
        }

        if (foundNext) {
          bot.visitedSet.add(foundNext.key);
          bot.stack.push({ r: foundNext.r, c: foundNext.c });
          bot.path.push({ r: foundNext.r, c: foundNext.c });

          if (foundNext.r === game.exit.r && foundNext.c === game.exit.c) {
            bot.finishTick = currentTick;
          }
        } else {
          // Dead end or fully explored branch -> backtrack
          const deadKey = `${cur.r},${cur.c}`;
          if (!bot.deadSet.has(deadKey)) {
            bot.deadSet.add(deadKey);
            bot.deadEnds.push({ r: cur.r, c: cur.c });
          }

          bot.stack.pop();

          if (bot.stack.length > 0) {
            const prev = bot.stack[bot.stack.length - 1];
            bot.path.push({ r: prev.r, c: prev.c });

            if (prev.r === game.exit.r && prev.c === game.exit.c) {
              bot.finishTick = currentTick;
            }
          }
        }
      }

      // Initialize global scripting API
      window.game = {
        elapsed: 0,
        size: { rows: ROWS, cols: COLS },
        spawn: { r: 0, c: 0 },
        exit: { r: ROWS - 1, c: COLS - 1 },
        bots: [],

        walls: function(r, c) {
          if (r < 0 || r >= ROWS || c < 0 || c >= COLS) {
            return { n: true, e: true, s: true, w: true };
          }
          const cell = grid[r][c];
          return { n: cell.n, e: cell.e, s: cell.s, w: cell.w };
        },

        reset: function(seed) {
          if (seed !== undefined && seed !== null) {
            currentSeed = Number(seed);
          } else {
            currentSeed = Math.floor(Math.random() * 1000000000);
          }

          prng = createPRNG(currentSeed);
          grid = generateMaze(ROWS, COLS, prng);
          this.elapsed = 0;

          // Shuffle direction priority permutations deterministically
          const perms = getPermutations(['N', 'E', 'S', 'W']);
          for (let i = perms.length - 1; i > 0; i--) {
            const j = Math.floor(prng() * (i + 1));
            [perms[i], perms[j]] = [perms[j], perms[i]];
          }

          this.bots = [];
          for (let i = 0; i < NUM_BOTS; i++) {
            this.bots.push({
              path: [{ r: this.spawn.r, c: this.spawn.c }],
              deadEnds: [],
              finishTick: null,

              // Internal exploration state
              dirOrder: perms[i % perms.length],
              stack: [{ r: this.spawn.r, c: this.spawn.c }],
              visitedSet: new Set([`${this.spawn.r},${this.spawn.c}`]),
              deadSet: new Set()
            });
          }

          animProgress = 1.0;
          updateUI();
          render();
        },

        tick: function(n) {
          const count = (n === undefined || n === null) ? 1 : Math.max(1, Math.floor(n));
          for (let step = 0; step < count; step++) {
            const allFinished = this.bots.every(b => b.finishTick !== null);
            if (allFinished) {
              break;
            }

            this.elapsed++;

            for (const bot of this.bots) {
              if (bot.finishTick === null) {
                stepBot(bot, this.elapsed);
              }
            }
          }

          animProgress = 1.0;
          updateUI();
          render();
        }
      };

      // UI elements
      const timerEl = document.getElementById('timer');
      const completedEl = document.getElementById('completed');
      const resetBtn = document.getElementById('reset');
      const playBtn = document.getElementById('playBtn');
      const stepBtn = document.getElementById('stepBtn');
      const seedInput = document.getElementById('seedInput');
      const canvas = document.getElementById('mazeCanvas');
      const ctx = canvas.getContext('2d');

      function updateUI() {
        timerEl.textContent = game.elapsed;
        const finishedCount = game.bots.filter(b => b.finishTick !== null).length;
        completedEl.textContent = `${finishedCount} / ${NUM_BOTS}`;
      }

      function render() {
        const width = canvas.width;
        const height = canvas.height;
        const cellW = width / COLS;
        const cellH = height / ROWS;

        ctx.clearRect(0, 0, width, height);

        // Maze background
        ctx.fillStyle = '#1e293b';
        ctx.fillRect(0, 0, width, height);

        // Spawn Cell Highlight
        ctx.fillStyle = 'rgba(34, 197, 94, 0.25)';
        ctx.fillRect(game.spawn.c * cellW, game.spawn.r * cellH, cellW, cellH);

        // Exit Cell Highlight
        ctx.fillStyle = 'rgba(239, 68, 68, 0.35)';
        ctx.fillRect(game.exit.c * cellW, game.exit.r * cellH, cellW, cellH);

        // Exit Marker Text
        ctx.fillStyle = '#ef4444';
        ctx.font = 'bold 11px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('EXIT', (game.exit.c + 0.5) * cellW, (game.exit.r + 0.5) * cellH);

        // Draw Maze Walls
        ctx.strokeStyle = '#64748b';
        ctx.lineWidth = 2;
        ctx.beginPath();

        for (let r = 0; r < ROWS; r++) {
          for (let c = 0; c < COLS; c++) {
            const x = c * cellW;
            const y = r * cellH;
            const w = game.walls(r, c);

            if (w.n) { ctx.moveTo(x, y); ctx.lineTo(x + cellW, y); }
            if (w.e) { ctx.moveTo(x + cellW, y); ctx.lineTo(x + cellW, y + cellH); }
            if (w.s) { ctx.moveTo(x, y + cellH); ctx.lineTo(x + cellW, y + cellH); }
            if (w.w) { ctx.moveTo(x, y); ctx.lineTo(x, y + cellH); }
          }
        }
        ctx.stroke();

        // Render Bots
        game.bots.forEach((bot, idx) => {
          const pathLen = bot.path.length;
          if (pathLen === 0) return;

          let renderR, renderC;

          if (bot.finishTick !== null) {
            renderR = game.exit.r;
            renderC = game.exit.c;
          } else if (pathLen === 1 || animProgress >= 1.0) {
            const curr = bot.path[pathLen - 1];
            renderR = curr.r;
            renderC = curr.c;
          } else {
            const prev = bot.path[pathLen - 2] || bot.path[pathLen - 1];
            const curr = bot.path[pathLen - 1];
            renderR = prev.r + (curr.r - prev.r) * animProgress;
            renderC = prev.c + (curr.c - prev.c) * animProgress;
          }

          const centerX = (renderC + 0.5) * cellW;
          const centerY = (renderR + 0.5) * cellH;
          const radius = Math.min(cellW, cellH) * 0.28;

          ctx.fillStyle = BOT_COLORS[idx % BOT_COLORS.length];
          ctx.beginPath();
          ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
          ctx.fill();

          ctx.strokeStyle = '#0f172a';
          ctx.lineWidth = 1;
          ctx.stroke();
        });
      }

      // Event Listeners
      resetBtn.addEventListener('click', () => {
        const val = seedInput.value.trim();
        if (val !== '') {
          game.reset(Number(val));
        } else {
          game.reset();
        }
      });

      playBtn.addEventListener('click', () => {
        isPlaying = !isPlaying;
        playBtn.textContent = isPlaying ? 'Pause' : 'Play';
      });

      stepBtn.addEventListener('click', () => {
        game.tick(1);
      });

      // Animation & Real-time Playback Loop
      let accumulator = 0;

      function loop(now) {
        const dt = now - lastFrameTime;
        lastFrameTime = now;

        const allFinished = game.bots.every(b => b.finishTick !== null);

        if (isPlaying && !allFinished) {
          accumulator += dt;
          if (accumulator >= TICK_INTERVAL) {
            accumulator %= TICK_INTERVAL;
            game.tick(1);
            animProgress = 0;
          } else {
            animProgress = accumulator / TICK_INTERVAL;
          }
        } else {
          animProgress = 1.0;
        }

        render();
        requestAnimationFrame(loop);
      }

      // Initial Setup
      game.reset(12345);
      requestAnimationFrame(loop);

    })();
  </script>
</body>
</html>
